(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c74"]=[{"id":"00006742","register_sub_id":"101","register_pk":"107725","name":"薗家住宅主屋","kana":"そのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県奄美市笠利町大字用安字竹作167-1","lat":28.40541996,"lng":129.65311437,"geo_status":"db","era":"明治期／昭和18・昭和25頃移築改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、鉄板葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0049","desc":"丘陵地に屋敷地を構え、オモテとトォゴラからなる分棟型の主屋が庭園の西奥に建つ。オモテは寄棟造鉄板葺で、トコと棚を備える主室８畳とネショ、コザからなり、玄関を構える。ヒキモンとよぶ横架材を使う構造で、奄美の伝統的な平面をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006742"},{"id":"00006093","register_sub_id":"101","register_pk":"107078","name":"潮音館（旧重富島津家住宅米蔵）","kana":"ちょうおんかん（きゅうしげとみしまづけじゅうたくこめぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市清水町31-8","lat":31.607412,"lng":130.572769,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積50㎡","structure_material":"石造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"46 － 0035","desc":"鹿児島港の北端に位置した島津久光四男珍彦（重富島津家）の別邸地内に遺るもと米蔵で，喫茶店として活用。桁行５間，梁間２間半規模，切妻造，桟瓦葺の平屋建で，妻上部に島津家の家紋を刻んだ石を嵌める。窓の庇を兼ねた楣石や軒蛇腹の石材加工の精度も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006093"},{"id":"00015533","register_sub_id":"101","register_pk":"533548","name":"沈壽官家茶室鶴壽軒","kana":"ちんじゅかんけちゃしつかくじゅけん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和後","pref":"鹿児島県","address":"鹿児島県日置市東市来町美山字藤之尾1715","lat":31.64357222,"lng":130.36003611,"geo_status":"db","era":"昭和44年／令和4年改修","year":1969,"year_source":"db","year_min":1969,"year_max":1969,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"46 - 0129","desc":"市街地西方にある薩摩焼窯元の茶室。敷地南西に建つ宝形造鉄板葺で南・東に軒支柱を立て軒を深くつくる。内部は茶室と水屋からなり、茶室は八畳間に床を上座に構え、床脇に茶道口を設ける。裏千家15代宗室監修による洗練された茶室で当家との交流を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015533"},{"id":"00010709","register_sub_id":"101","register_pk":"201283","name":"蛭川家住宅（旧遠矢家住宅）蔵","kana":"ひるかわけじゅうたく（きゅうとおやけじゅうたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県曽於市大隅町恒吉字馬場566","lat":31.586778,"lng":130.908737,"geo_status":"db","era":"慶応3年（1867）","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"46 － 0117","desc":"主屋の東方に西面して建つ二階建の蔵。桁行五メートル、梁間四メートルを測り、正面には一間の下屋が付く。小屋組は登梁形式。屋根は切妻造の瓦葺とし、軒を深く出す。恒吉城下の郷士宅において、年代の明らかな遺構として希少で、歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010709"},{"id":"00010708","register_sub_id":"101","register_pk":"201282","name":"蛭川家住宅（旧遠矢家住宅）主屋","kana":"ひるかわけじゅうたく（きゅうとおやけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県曽於市大隅町恒吉字馬場566","lat":31.586838,"lng":130.908559,"geo_status":"db","era":"江戸末期／昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"46 － 0116","desc":"大隅半島の付け根に位置する恒吉城下の郷士宅。主屋は表に玄関、次の間、座敷の三室を一列に並べ、裏に納戸、小座、ナカエを配する、当地の伝統的な武家住宅の間取りとし、庭に面して縁を廻らせる。当地における江戸末期の武家住宅の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010708"},{"id":"00010710","register_sub_id":"101","register_pk":"201284","name":"蛭川家住宅（旧遠矢家住宅）門","kana":"ひるかわけじゅうたく（きゅうとおやけじゅうたく）もん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県曽於市大隅町恒吉字馬場566","lat":31.586711,"lng":130.908652,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"46 － 0118","desc":"敷地正面の南辺を画す石垣の間に建つ。本柱をのばして棟木を直接支持し、背面の控柱で桁を受けるとともに、本柱と控柱間をつなぐ飛貫を腕木状に前まで延ばして正面の桁を受ける。門扉に八双金物を飾るなど、武家住宅の屋敷の表構えに相応しい風格を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010710"},{"id":"00006643","register_sub_id":"101","register_pk":"107626","name":"松下家住宅石垣","kana":"まつしたけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字東塩屋27024","lat":31.25344108,"lng":130.38196283,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、総延長78m","structure_material":"石造","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0057","desc":"敷地の東から南、西面にかけて断続的に残り、総延長７８ｍに及ぶ。２段から８段に切石を積み、高さは０．５３ｍから２．７ｍで、西側では特に高い。東面中央において敷地内に折れ曲がり、門口とし、敷地西南隅では円弧状に造る。土蔵等とともに街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006643"},{"id":"00006641","register_sub_id":"101","register_pk":"107624","name":"松下家住宅主屋","kana":"まつしたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字東塩屋27024","lat":31.25337949,"lng":130.38211101,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0055","desc":"敷地の西寄りに東面する木造平屋建。ナカエとオモテを雁行型に建てる伝統的な形式。桟瓦葺で周囲に下屋庇を設け、ナカエは切妻造妻入、オモテはナカエ側を切妻造、背面を入母屋造とする。上屋は軒出が短く、妻を含め漆喰で塗り込め、安定感のある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006641"},{"id":"00006642","register_sub_id":"101","register_pk":"107625","name":"松下家住宅土蔵","kana":"まつしたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字東塩屋27024","lat":31.253471,"lng":130.382034,"geo_status":"db","era":"明治前期／昭和中期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0056","desc":"主屋の南、敷地南端に位置する。桁行３間梁間２間半規模の２階建土蔵２棟が、東西棟で連続し一体として建つ。切妻造桟瓦葺で、基礎を切石布積とし、外壁は漆喰で軒まで塗り込める。西側妻に出入口を設け、内部を２室に間仕切る。装飾性のない簡明な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006642"},{"id":"00006472","register_sub_id":"101","register_pk":"107455","name":"森山家住宅旧作業場","kana":"もりやまけじゅうたくきゅうさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"鹿児島県","address":"鹿児島県姶良市加治木町朝日町172","lat":31.73423725,"lng":130.66716409,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、スレート葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"46 － 0048","desc":"主屋の後方に建つ。建築面積８０㎡、木造平屋建、波形スレート葺。島津斉彬が嘉永４年に興した集成館の建物を移築改造したと伝える。外壁は波形鉄板張であるが、軸組は古材をよく残しており、地棟木に架けた登梁に母屋束を立てるなど、独特な架構法になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006472"},{"id":"00005689","register_sub_id":"101","register_pk":"106677","name":"森山家住宅主屋","kana":"もりやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市加治木町朝日町172","lat":31.73439743,"lng":130.66715768,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積218㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0025","desc":"南北に長い敷地の北西隅にあり，南北棟で東面して建つ。正面中央に入母屋造の玄関を設け，北は座敷や離れ等の居室部，南は台所や土間となる。全体に良質の材を用いた丁寧なつくりの和風住宅で，欄間等の造作を巧緻に仕上げるなど，要所に当時の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005689"},{"id":"00002870","register_sub_id":"101","register_pk":"103860","name":"森山家住宅土蔵","kana":"もりやまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市加治木町朝日町172","lat":31.73439955,"lng":130.66735972,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"石造及び土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"石造及び土蔵造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"46 － 0011","desc":"桁行約１７ｍ，梁間約５ｍの蔵。腰部を石造とし，その上に半間毎に柱を立てて土蔵としている。内部は南北２室に分け，２階を設けている。西面及び南面に入口３カ所を開く他，数カ所に窓を設けている。通例より高くまで石造部分を持つことが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002870"},{"id":"00012081","register_sub_id":"101","register_pk":"211161","name":"八板家住宅主屋","kana":"やいたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鹿児島県","address":"鹿児島県西之表市西町6989","lat":30.735063,"lng":130.994379,"geo_status":"db","era":"江戸末期／昭和30年代改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積151㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"46-121","desc":"西之表旧港に位置する。間口四間半、奥行七間半、妻入で、通りに東面する。土間に沿って、二列各二室を並べ、奥に中の間を介し奥座敷を突出させる。中の間上部に二階を設け、吹抜けの天井は船底型とする。港町に残る近世町家の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012081"},{"id":"00006637","register_sub_id":"101","register_pk":"107620","name":"安田家住宅主屋","kana":"やすだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字下村25820","lat":31.25469,"lng":130.394241,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0051","desc":"敷地の北寄りに南面して建つ。桁行７間梁間４間半規模、東西棟の桟瓦葺で、西を寄棟造、東を入母屋造とし、正・背面に下屋庇を付ける。当初は西に土間、次にシモザとナカエ、東にオモテ他４室を配した。当地方における明治期の新たな傾向が窺える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006637"},{"id":"00006638","register_sub_id":"101","register_pk":"107621","name":"安田家住宅土蔵一","kana":"やすだけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字下村25820","lat":31.25456224,"lng":130.39416275,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0052","desc":"主屋の西側に位置し、通りに接する。桁行３間梁間２間半の土蔵造２階建。南北棟の切妻造桟瓦葺で、主屋側の東面に庇付の出入口を設け、片引戸をたて、北面に窓を２ヶ所穿つ。基礎は切石布積で、外壁は漆喰で仕上げる。質実簡明な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006638"},{"id":"00006639","register_sub_id":"101","register_pk":"107622","name":"安田家住宅土蔵二","kana":"やすだけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字下村25820","lat":31.25450523,"lng":130.39419466,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0053","desc":"土蔵一の南側に南北棟で連続して建ち、通り側の屋敷構えを造る。桁行３間梁間２間半で土蔵造２階建。切妻造桟瓦葺で、土蔵一より棟高がやや低い。出入口を東面に設け、南面に窓を開ける。基礎を切石布積とし、外壁を漆喰で仕上げ、正面のみ軒まで塗り込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006639"},{"id":"00006640","register_sub_id":"101","register_pk":"107623","name":"安田家住宅門及び石垣","kana":"やすだけじゅうたくもんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字下村25820","lat":31.2548066,"lng":130.39426878,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"門 石造、間口3.1m、石垣 石造、総延長77m","structure_material":"門 石造","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0054","desc":"門は屋敷地の北側西端に位置し、門の両側から石垣が周囲に巡る。門は間口３．１ｍで、方柱の門柱を建てる。石垣は２段から５段に切石を積み、高さ０．７ｍから１．４ｍで、総延長７７ｍに及ぶ。石垣に接して生垣が植えられるなど、歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006640"},{"id":"00006563","register_sub_id":"101","register_pk":"107546","name":"横峯家住宅主屋","kana":"よこみねけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町永里1226","lat":31.34512188,"lng":130.43542866,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、茅葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0044","desc":"東面する敷地中央に建つ。桁行４間半，梁間４間のオモテに，桁行４間，梁間３間のナカエをややずらして連結し，棟を直交させてつくる。木造平屋建，寄棟造，茅葺とする。知覧型二つ家と呼ばれる形式で，南九州の民家形式を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006563"},{"id":"00006636","register_sub_id":"101","register_pk":"107619","name":"吉田家住宅土蔵","kana":"よしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県南九州市知覧町南別府字濱ノ上23295他","lat":31.25285472,"lng":130.40992801,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"46 － 0058","desc":"屋敷地の中央東寄り、主屋に近接して建つ。桁行３間半梁間２間半の土蔵造２階建、南北棟の切妻造妻入桟瓦葺。南面に出入口、東と北面に窓を開ける。外壁は漆喰塗で、軒まで塗り込める。基礎は切石布積で、３．８ｍに達する長い石も使われ、目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006636"},{"id":"00006179","register_sub_id":"101","register_pk":"107163","name":"新垣家住宅石垣","kana":"あらがきけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.22997693,"lng":127.71173068,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、延長58m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0037","desc":"敷地の南辺，西辺及び北辺を廻る石垣で，総延長５８ｍ，厚さ６０～７０ｃｍで，高さは１～１．８ｍとする。琉球石灰岩の乱積で，表面を削って整形し，特にヒンプンに続く出入口の部分は精緻に表面を整えている。敷地景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006179"},{"id":"00005763","register_sub_id":"101","register_pk":"106751","name":"新垣家住宅主屋","kana":"あらがきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.22994603,"lng":127.71163603,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0035","desc":"南面する敷地のやや北方に建つ。桁行６間半，梁間４間の規模で，木造平屋建，寄棟造，瓦葺とする。東側に６畳間及び４畳半間２室を並べ，西側に板の間の台所及び土間をとる。板の間南側に玄関を構える。赤瓦屋根の外観は沖縄独特の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005763"},{"id":"00006180","register_sub_id":"101","register_pk":"107164","name":"新垣家住宅東池","kana":"あらがきけじゅうたくひがしいけ","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.22991476,"lng":127.71170873,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、面積5.8㎡、石垣延長5.9m付","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0039","desc":"主屋の東側の敷地東辺に接して形成された石垣付の池である。南北７ｍ，東西１．４ｍの規模の石垣に，主屋側に長方形の堀込みをつくり，２．８ｍ×０．８ｍの池とする。その他の３方には石垣を１．８ｍの高さまで築き，特徴ある外観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006180"},{"id":"00006138","register_sub_id":"101","register_pk":"107122","name":"新垣家住宅ヒンプン","kana":"あらがきけじゅうたくひんぷん","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.2298688,"lng":127.71160298,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、延長3.6m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0036","desc":"主屋の南側，道路との間に位置する。東西３．６ｍで，厚さ６０ｃｍ，高さ１．７ｍとする。石造で，琉球石灰岩を乱積にし，表面を整形して断面台形の板状につくる。正面入口からの目隠しとなり，沖縄独特の敷地景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006138"},{"id":"00006139","register_sub_id":"101","register_pk":"107123","name":"新垣家住宅フール","kana":"あらがきけじゅうたくふーる","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.22998849,"lng":127.71155435,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、面積13㎡","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0038","desc":"主屋西側の石垣に接して，琉球石灰岩の切石で造られた豚の飼育小屋を兼ねた便所である。南北６ｍ，東西２ｍの規模で，３つに仕切られ，西側には３連のアーチ形の屋根を付ける。大小の切石を巧みに組み上げ，沖縄の特徴ある敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006139"},{"id":"00006181","register_sub_id":"101","register_pk":"107165","name":"新垣家住宅南池","kana":"あらがきけじゅうたくみなみいけ","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県那覇市首里末吉町2-124-2","lat":26.22985727,"lng":127.71166908,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、面積3.8㎡","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0040","desc":"主屋の南東の出入口近くに位置する。長辺２．５ｍ，短辺１．６ｍの規模で，不整形な多角形平面とする。周囲を琉球石灰岩の自然石で囲み，内側を漆喰で仕上げる。その外側に溝を設け排水路とする。主屋周囲の石畳と一体化し，特徴ある敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006181"},{"id":"00010905","register_sub_id":"101","register_pk":"201740","name":"石垣やいま村旧大浜家住宅主屋","kana":"いしがきやいまむらきゅうおおはまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字名蔵967-1","lat":24.40371093,"lng":124.14465895,"geo_status":"db","era":"明治40／平成20移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"47 ‐ 0084","desc":"石垣市中心部に所在した住宅。東より、床の間付の一番座、仏壇をもつ二番座、三番座及び四番座を並べ、背面に裏座をおき、南東面に雨端を廻らし、南東隅に玄関を付す。西には台所を突出させる。年代が明らかで規模も充実し、近代的な要素を備えた琉球民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010905"},{"id":"00010906","register_sub_id":"101","register_pk":"201741","name":"石垣やいま村旧喜舎場家住宅主屋","kana":"いしがきやいまむらきゅうきしゃばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県石垣市字名蔵967-1","lat":24.40375323,"lng":124.14414587,"geo_status":"db","era":"大正12／平成20移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"47 ‐ 0085","desc":"石垣市中心部に所在した住宅。背面側に玄関を設ける都合上、一番座側面に床を構える変則的な平面となる。屋根は背面玄関側に入母屋破風を見せ、隣接する台所と三番座に別々に屋根を架ける複雑な屋根形状とするなど、市街地における琉球民家の近代的展開を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010906"},{"id":"00006240","register_sub_id":"101","register_pk":"107224","name":"入嵩西家住宅井戸","kana":"いりたけにしけいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字新川151","lat":24.34984349,"lng":124.15002874,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、面積0.7㎡","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0044","desc":"敷地南西角に位置する。直径約９０ｃｍ，深さ約１０ｍ。井筒は４枚のサンゴ石を厚さ１３ｃｍに加工し，円形に組み合わせる。現在は，コンクリート製の円形の蓋を載せる。主屋建設より前に掘られたとされる。小規模ながら沖縄の特徴ある敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006240"},{"id":"00006239","register_sub_id":"101","register_pk":"107223","name":"入嵩西家住宅石垣","kana":"いりたけにしけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県石垣市字新川151","lat":24.34983265,"lng":124.15027502,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"石造、延長53m、門柱2基付","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0043","desc":"敷地の東面及び南面を仕切る総延長約５３ｍの石垣。敷地南側，西端から１６ｍの位置に３ｍ余の門口を開く。幅１５０ｃｍ前後，高さ４５ｃｍ，厚さ２５ｃｍの切石を４段積み重ね，門口には１対の石造の門柱を立て，風格ある敷地構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006239"},{"id":"00006182","register_sub_id":"101","register_pk":"107166","name":"入嵩西家住宅主屋","kana":"いりたけにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字新川151","lat":24.34987251,"lng":124.15018709,"geo_status":"db","era":"明治44頃／昭和30頃改造","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0041","desc":"北，東，南の各面が接道する敷地のほぼ中央に南面して建つ。木造平屋建，寄棟造，瓦葺とする。南側に６畳２室と４畳２室を並べ，北側に裏座と板間を並べ，西側に板の間の台所をとる。部屋数の多い大規模な赤瓦屋根の伝統的農家で，沖縄独特の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006182"},{"id":"00006183","register_sub_id":"101","register_pk":"107167","name":"入嵩西家住宅マイグスク","kana":"いりたけにしけじゅうたくまいぐすく","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県石垣市字新川151","lat":24.34979081,"lng":124.15014719,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"石造、延長5.7m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0042","desc":"主屋の南側，道路との間に位置する。東西５．７ｍ，厚さ２５ｃｍ，高さ１．５ｍの目隠し壁。切石を３段に積み，両袖を１石とし，上部に笠石を渡す。広大な屋敷構にふさわしい重みのある外観で，主屋，石垣と一体的に伝統的な敷地景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006183"},{"id":"00006001","register_sub_id":"101","register_pk":"106986","name":"入福浜家住宅主屋","kana":"いりふくはまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国160","lat":24.46986614,"lng":123.00316606,"geo_status":"db","era":"大正初期／平成14改築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"47 － 0024","desc":"敷地中央に南面して建つ。桁行６間半，梁間５間の規模で，木造平屋建，赤瓦葺とする。南側に１番座から３番座までを並べ，２番座の北側に床の間，仏壇を置き，北側に裏座３室を配する。南面と東面に雨端柱を立てる。地域的特色を良く残す貴重な木造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006001"},{"id":"00005699","register_sub_id":"101","register_pk":"106687","name":"大盛家住宅石垣","kana":"おおもりけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡竹富町字小浜15","lat":24.33915033,"lng":123.97781513,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造、延長65m","structure_material":"石造","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0020","desc":"敷地の南面から西面，北面を囲むサンゴ石灰岩の野面積石垣。折曲り延長６５ｍ，基底幅０．８ｍ，高さ１．５～１．７ｍ。南面中央を２ｍ開けて表門とし，西寄りに脇門を開く。人頭大の丸石を中心に空積とするが，表口の両脇部では大振りの板石を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005699"},{"id":"00005700","register_sub_id":"101","register_pk":"106688","name":"大盛家住宅井戸","kana":"おおもりけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡竹富町字小浜15","lat":24.33963635,"lng":123.9782784,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造、面積4.3㎡","structure_material":"石造","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0021","desc":"敷地の南面石垣の内側，ヒンプンの南西に位置する。直径１ｍ，高さ０．６ｍの円形井戸枠は，サンゴ石灰岩６枚で組む。井戸枠上には半月形の蓋石１枚を載せる。井戸の周囲には南北２．４ｍ，東西１．７ｍの洗い場がある。往時は隣家へも生活用水を供給した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005700"},{"id":"00005697","register_sub_id":"101","register_pk":"106685","name":"大盛家住宅主屋","kana":"おおもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡竹富町字小浜15","lat":24.3390829,"lng":123.97790371,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0018","desc":"南下がりの敷地のほぼ中央に南面して建つ木造平屋建で，桁行５間半，梁間４間半の寄棟造平入。屋根は琉球赤瓦葺，目地漆喰塗とし，南面と東面に縁がつく。内部は整形四間取で西に板間があり，表側２室は南の畳敷内縁を含めて２０畳大とし，地区の集会にも用いた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005697"},{"id":"00005698","register_sub_id":"101","register_pk":"106686","name":"大盛家住宅ヒンプン","kana":"おおもりけじゅうたくひんぷん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡竹富町字小浜15","lat":24.33904175,"lng":123.97789351,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造、面積3.6㎡","structure_material":"石造","registered":"2006.08.03(平成18.08.03)","register_no":"47 － 0019","desc":"主屋の正面から約４ｍ離れ，表門の内側に位置する。長さ６ｍ，高さ１．６ｍ，基底幅０．６ｍ。サンゴ石灰岩切石の空積で，精緻に加工して組み合わせている。上部は屋根形に造り，半円断面の石で棟積を表している。屋敷構えに欠かせない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005698"},{"id":"00008800","register_sub_id":"101","register_pk":"149521","name":"沖縄市立ふるさと園旧久場家住宅主屋","kana":"おきなわしりつふるさとえんきゅうくばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県沖縄市胡屋5-831","lat":26.32792962,"lng":127.80425961,"geo_status":"db","era":"大正13年／昭和60年移築","year":1924,"year_source":"converted","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"47 － 0076","desc":"桁行15ｍ梁間8.3ｍの木造平屋建で、南面して建つ。寄棟造本瓦葺で、正面から東面にかけて雨端をまわす。1番座から3番座と各裏座が東から並び、西端に台所を置く。1番座にはトコ、2番座には仏壇を構え、裏座は板敷で、間仕切らない。伝統的な沖縄民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008800"},{"id":"00008801","register_sub_id":"101","register_pk":"149522","name":"沖縄市立ふるさと園旧久場家住宅ヒンプン","kana":"おきなわしりつふるさとえんきゅうくばけじゅうたくひんぷん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県沖縄市胡屋5-831","lat":26.32780273,"lng":127.80423152,"geo_status":"db","era":"大正13年／昭和61年移築","year":1924,"year_source":"converted","year_min":1924,"year_max":1924,"year_label":null,"structure":"石造、延長4.6m","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"47 － 0077","desc":"沖縄の伝統的な屋敷構えに倣い、敷地門口の正面、主屋前方に位置する。布積のヒンプン。港川産の粟石を比較的大きく切り出し、4段積み上げ、高さ1.7ｍ、幅4.6ｍ、厚さ20㎝を測る。石造の典型的なヒンプンであり、大きめ切石が重厚感を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008801"},{"id":"00008802","register_sub_id":"101","register_pk":"149523","name":"沖縄市立ふるさと園旧平田家住宅マチフール","kana":"おきなわしりつふるさとえんきゅうひらたけじゅうたくまちふーる","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"沖縄県","address":"沖縄県沖縄市胡屋5-831","lat":26.32797437,"lng":127.80414256,"geo_status":"db","era":"大正13年／昭和61年移築","year":1924,"year_source":"converted","year_min":1924,"year_max":1924,"year_label":null,"structure":"石造、面積17㎡","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"47 － 0078","desc":"琉球石灰岩を用いた石造施設。東西1.3ｍ南北2.2ｍを切石で囲い、北側後寄りにアーチ型に屋根を架ける豚飼育場を東西に並べる。アーチ屋根上部には植栽を設ける。豚飼育場の西方に石を組み肥溜を配し、前方には便所を設ける。フールの特徴的な形態を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008802"},{"id":"00007160","register_sub_id":"101","register_pk":"108142","name":"おきなわワールド旧伊礼家住宅主屋","kana":"おきなわわーるどきゅういれいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県南城市玉城字前川1384他","lat":26.13845827,"lng":127.75115646,"geo_status":"db","era":"明治後期／平成7移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"47 － 0068","desc":"桁行７．６ｍ梁間６．８ｍ、南北棟、寄棟造本瓦葺、木造平屋建の「うふや」の南面に、桁行３．８ｍ梁間３．９ｍの「とんぐわ」が取り付き、分棟型沖縄民家の形式を留める。「うふや」は一番座、二番座、板間、裏座２室からなり、北面と東面正面に雨端をまわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007160"},{"id":"00007161","register_sub_id":"101","register_pk":"108143","name":"おきなわワールド旧上里家住宅主屋","kana":"おきなわわーるどきゅううえざとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県南城市玉城字前川1384他","lat":26.13856445,"lng":127.75121755,"geo_status":"db","era":"昭和9頃／平成7移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"47 － 0069","desc":"桁行１２ｍ梁間７．６ｍ規模、寄棟造本瓦葺の木造平屋建で、東面表側に北から一番座、二番座、板間、台所土間を並べ、西側に裏座３室を配する。北面から東面板間まで縁側を通し、一番裏座西面を除いた四周に雨端をまわした沖縄の伝統的民家のつくりをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007161"},{"id":"00007158","register_sub_id":"101","register_pk":"108140","name":"おきなわワールド旧喜屋武家住宅主屋","kana":"おきなわわーるどきゅうきゃんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県南城市玉城字前川1384他","lat":26.13862232,"lng":127.7511093,"geo_status":"db","era":"明治後期／平成7年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"47 － 0066","desc":"桁行１４ｍ梁間７．８ｍ規模、寄棟造本瓦葺の木造平屋建で、南半の西面表側に一番座と二番座を並べて縁側を配し、東側には裏座２室を置き、北半は居間、土間台所等とする。沖縄の伝統的民家の形式をもち、雨端が一番座南面から西面土間台所の前までまわる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007158"},{"id":"00007159","register_sub_id":"101","register_pk":"108141","name":"おきなわワールド旧田場家住宅主屋","kana":"おきなわわーるどきゅうたばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県南城市玉城字前川1384他","lat":26.13842241,"lng":127.75146041,"geo_status":"db","era":"明治後期／平成7移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"47 － 0067","desc":"桁行１５ｍ梁間６．８ｍ規模、南北棟、寄棟造本瓦葺の木造平屋建で、西面縁側に沿って南から板間、一番座、二番座を並べ、北側に土間台所を配し、西面と南面とに雨端をまわす。沖縄の伝統的民家の平面形式とは異なり、裏座がなく東面に廊下を通すのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007159"},{"id":"00007162","register_sub_id":"101","register_pk":"108144","name":"おきなわワールド旧知念家住宅フール","kana":"おきなわわーるどきゅうちねんけじゅうたくふーる","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県南城市玉城字前川1384他","lat":26.13897193,"lng":127.7512555,"geo_status":"db","era":"明治30頃／平成8移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"石造、面積16㎡","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"47 － 0070","desc":"琉球石灰岩の切石で築造される。平面は東西３．４ｍ南北３．５ｍ規模とし、内部は２．１ｍ×１．３ｍの２室に区切り、西側には偏平アーチ状天井の覆いを架け、東正面側には石敷が設けられる。隔壁の開口、床の傾斜、石敷の穴加工などが往時の使い方を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007162"},{"id":"00006120","register_sub_id":"101","register_pk":"107104","name":"神山家住宅石垣","kana":"かみやまけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡竹富町字黒島1522","lat":24.23556308,"lng":124.01311758,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、延長87m","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0032","desc":"屋敷地の南辺西方の一部を除き四周を囲う。延長８７．４ｍ，珊瑚石灰岩の野面積で，高さ１．３～１．４ｍ，幅０．６～０．８ｍ規模。南辺中央の門部は間口３ｍで，両端を切石の木端建とし，西辺や出隅部は大きめの石を用いるなど景観に配慮したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006120"},{"id":"00006122","register_sub_id":"101","register_pk":"107106","name":"神山家住宅井戸","kana":"かみやまけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡竹富町字黒島1522","lat":24.23550672,"lng":124.0129133,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、面積1.1㎡","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0034","desc":"屋敷地西南隅，外周石垣の西南入隅部に位置する。直径０．９ｍ，深さ４．２ｍの掘り抜き井戸で，地上部は石積基礎の上に凹板形の珊瑚石灰岩３枚で内転びの円筒状の井戸枠をつくる。地下水が豊富でない沖縄の離島における水事情を物語る施設として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006122"},{"id":"00005074","register_sub_id":"101","register_pk":"106064","name":"神山家住宅主屋","kana":"かみやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県八重山郡竹富町字黒島1522","lat":24.23549195,"lng":124.01308123,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"47 － 0007","desc":"東筋集落の民家で，南面する敷地の中央に南面して建つ。桁行７間，梁間５間の規模で，寄棟造，赤瓦葺，木造平屋建。一番座を８畳間として仏壇を付属し，脇に小規模な床の間を構える。元は茅葺で，軒を低く造る古い形式をもつ。離島の古い民家形式を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005074"},{"id":"00006121","register_sub_id":"101","register_pk":"107105","name":"神山家住宅水タンク","kana":"かみやまけじゅうたくみずたんく","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"沖縄県","address":"沖縄県八重山郡竹富町字黒島1522","lat":24.23545884,"lng":124.01296944,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、面積3.6㎡","structure_material":"鉄筋コンクリート造","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0033","desc":"石垣門部の西方に位置し，屋敷地前面道路に南面を見せて建つ。東西１．５ｍ，南北２．４ｍの平面規模，高さ１．７５ｍの鉄筋コンクリート造貯水槽で，主屋屋根からの雨水を竹樋で引き，陸屋根北方に濾過タンクを載せる。東面に「昭和十三年旧六月建設」を刻む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006121"},{"id":"00010711","register_sub_id":"101","register_pk":"201285","name":"旧國場家住宅主屋","kana":"きゅうこくばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1437-1","lat":26.429232,"lng":127.774497,"geo_status":"db","era":"昭和5年／平成23年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"47－0083","desc":"赤い琉球瓦の入母屋造屋根で、北東を正面として建つ。正面右より十畳大の一番座、二番座、三番座と続き、背面に裏座と突出する土間の台所を並べる。平面構成から軸組まで伝統形式であるが、一番座正面に設けた玄関庇やガラス戸建具は近代的な要素といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010711"},{"id":"00011433","register_sub_id":"101","register_pk":"209270","name":"旧名城家住宅石垣","kana":"きゅうなしろけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県島尻郡伊是名村字勢理客1547","lat":26.93105894,"lng":127.92584886,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造、延長116m","structure_material":"石造","registered":"2016.11.29(平成28.11.29)","register_no":"47－0087","desc":"敷地の周囲四方に積まれた石垣である。珊瑚石を野面積とし、高さ一・五メートル強、基底幅〇・七メートル、折曲り延長一一六メートルを測る。南正面には出入口を開ける。角は曲線状に仕上げ、現在では希少となった伊是名村での伝統的な屋敷構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011433"},{"id":"00011432","register_sub_id":"101","register_pk":"209269","name":"旧名城家住宅主屋","kana":"きゅうなしろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県島尻郡伊是名村字勢理客1547","lat":26.930952,"lng":127.925864,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"47－0086","desc":"尚円王の出身地で知られる伊是名島に建つ。琉球民家の伝統に則り、座敷部と台所部が棟を違え、琉球赤瓦葺、目地漆喰塗とする。座敷部は一番座と二番座、各裏座とし、大きな雨端を持つ。二番座を前後二室に区切るのは、当地の上層民家に特徴的な平面と言える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011432"},{"id":"00005073","register_sub_id":"101","register_pk":"106063","name":"金城増治家住宅石垣","kana":"きんじょうますはるけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県糸満市字真壁223","lat":26.10543832,"lng":127.69138651,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"石造、延長30m","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"47 － 0006","desc":"敷地正面の敷地境に造られた石垣。琉球石灰岩を積み上げ，長さ３０ｍ，高さ１．７ｍの規模で，上部に切石を並べる。石垣の内側は土盛りされ，生垣となる。規模の比較的大きな石垣で，大きな石を組み，良好な状況で保存され，屋敷構の構成の一つとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005073"},{"id":"00005072","register_sub_id":"101","register_pk":"106062","name":"金城増治家住宅井戸","kana":"きんじょうますはるけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県糸満市字真壁223","lat":26.10567187,"lng":127.69129821,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"石造、面積2.1㎡","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"47 － 0005","desc":"主屋の西側，敷地境近くに位置する。直径約１．１ｍの円形石積みで，深さ約８．６ｍの掘り抜き井戸である。取水部側を切石積みとし，背面を野面積みとする。井戸南側に高さ２ｍ，北側に１ｍの方形の石柱が立つ。屋敷構の構成の一つとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005072"},{"id":"00004874","register_sub_id":"101","register_pk":"105864","name":"金城増治家住宅主屋","kana":"きんじょうますはるけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県糸満市字真壁223","lat":26.10556642,"lng":127.69142986,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"47 － 0003","desc":"琉球王府時代に形成された真壁集落の中央に位置する。桁行７間梁行４間半強規模，寄棟造の木造平屋建，赤瓦葺で，東・南面に雨端を廻し，内部は８畳の一番座と二番座等から構成される伝統的な形式を踏襲する。１間以上幅の縁側が醸し出す開放性に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004874"},{"id":"00005071","register_sub_id":"101","register_pk":"106061","name":"金城増治家住宅フール","kana":"きんじょうますはるけじゅうたくふーる","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県糸満市字真壁223","lat":26.10561252,"lng":127.69126244,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"石造、面積7.3㎡","structure_material":"石造","registered":"2005.11.10(平成17.11.10)","register_no":"47 － 0004","desc":"南面する敷地中央の主屋の西側に位置し，琉球石灰岩の２連のフール。長辺４．１ｍ，短辺３．１ｍ，最高高さ１．１ｍの規模である。屋根部分は失われているが，異形の石材を組んだ石造部分は良好に保存され，屋敷構の構成の一つとして貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005071"},{"id":"00006312","register_sub_id":"101","register_pk":"107295","name":"久部良家住宅石垣","kana":"くぶらけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国365","lat":24.46707247,"lng":123.00478082,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、延長39m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0057","desc":"敷地の東辺と南辺に積まれた石垣である。珊瑚石灰岩の野面積になり、総延長３９ｍ、高さ１．３ｍ、幅０．７ｍ。隅部及び門口には大きめの石を使用して堅固に積む。主屋と一体となって、沖縄地方固有の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006312"},{"id":"00006311","register_sub_id":"101","register_pk":"107294","name":"久部良家住宅主屋","kana":"くぶらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国365","lat":24.4670888,"lng":123.00470769,"geo_status":"db","era":"明治中期／昭和15移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0056","desc":"石垣市にあった石垣殿内の建物を移築したと伝え、敷地の中央に建つ。桁行１２ｍ、梁間１１ｍ、木造平屋建、寄棟造本瓦葺。一番座と二番座は１０畳間と広く、各裏座とともに田の字型平面とする。雨端柱の通りに改変がみられるが、主体部は旧規を良くとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006311"},{"id":"00006248","register_sub_id":"101","register_pk":"107232","name":"末吉家住宅石垣","kana":"すえよしけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港41","lat":25.95344039,"lng":131.28694468,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造、延長69m","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0051","desc":"幹線道路に面する角地に位置し，ほぼ矩形の敷地の西面と南面に築かれる。延長６９ｍ，天端幅６５ｃｍ～１００ｃｍの厚い壁体からなる石造構造物。方形に近い不整形の石灰岩を巧みに組み合わせて築く。町の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006248"},{"id":"00006247","register_sub_id":"101","register_pk":"107231","name":"末吉家住宅主屋","kana":"すえよしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港41","lat":25.95364259,"lng":131.28692356,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造平屋建、鉄板葺、建築面積107㎡","structure_material":"石造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"47 － 0050","desc":"燐鉱の積出港として利用された西港に通じる，島北西部の幹線道路に面して建つ。桁行１３ｍ，梁間８．４ｍ規模，寄棟造，平入の石造平屋建。角部をコンクリートで固め，壁面を石灰岩の布積とし，内部造作にはビロウを用いる。島で最初期の住宅地開発の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006247"},{"id":"00009246","register_sub_id":"101","register_pk":"164799","name":"北谷町うちなぁ家主屋（旧目取真家住宅主屋）","kana":"ちゃたんちょううちなぁやしゅおく（きゅうめどるまけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県中頭郡北谷町字上勢頭830-2","lat":26.3278151,"lng":127.76838903,"geo_status":"db","era":"明治23年／平成17年移築","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"敷地中央に南面して建つ。建築面積104平方メートル、木造平屋建、寄棟造本瓦葺で、南東面に雨端を廻らす。東から1番座、2番座、板敷の3番座と並べ、西端に台所を配す。1番座にトコ、2番座には仏壇を設け、北側を裏座とする。伝統的な沖縄民家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009246"},{"id":"00009247","register_sub_id":"101","register_pk":"164800","name":"北谷町うちなぁ家ふーる（旧崎原家住宅ふーる）","kana":"ちゃたんちょううちなぁやふーる（きゅうさきはらけじゅうたくふーる）","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県中頭郡北谷町字上勢頭830-2","lat":26.32781129,"lng":127.76825958,"geo_status":"db","era":"明治前期／平成18年移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"石造、面積17㎡","structure_material":"石造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"間口4メートル奥行4.6メートルの琉球石灰岩を用いた2連式のふーるである。北半を東西2室に仕切り、各々奥行1.6メートルのアーチ状の屋根を架ける。手前は石組みの飼育場を東西に並べ、床を石敷きとする。典型的なふーるの形式をよくとどめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009247"},{"id":"00006961","register_sub_id":"101","register_pk":"107943","name":"東迎家住宅石垣","kana":"とうげいけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国151-1","lat":24.4692208,"lng":123.00437958,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"石造、延長9.5m","structure_material":"石造","registered":"2008.03.07(平成20.03.07)","register_no":"47 － 0065","desc":"東側の道路から屋敷地南辺を通り主屋へ通じる通路と前庭を画する石垣。東西延長９．５ｍ、高さ約１．５ｍ、幅０．７ｍの規模を有する。主屋建設時の基礎掘削で生じた石を利用して建設された。沖縄の伝統的な敷地景観を構成する遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006961"},{"id":"00006960","register_sub_id":"101","register_pk":"107942","name":"東迎家住宅イチタライ","kana":"とうげいけじゅうたくいちたらい","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国151-1","lat":24.46931576,"lng":123.00444562,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積3.0㎡","structure_material":"石造","registered":"2008.03.07(平成20.03.07)","register_no":"47 － 0064","desc":"主屋東面の小高い所、東塀に近接する位置にある。南北１．８ｍ東西１．４ｍで、高さ０．９４ｍになり、砂岩を掘り込み、造られる。規模の大きいイチタライ（石盥）は防火用の水槽として利用されており、その中でも有数の規模をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006960"},{"id":"00006959","register_sub_id":"101","register_pk":"107941","name":"東迎家住宅井戸","kana":"とうげいけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国151-1","lat":24.46929669,"lng":123.00428317,"geo_status":"db","era":"明治前期／昭和中期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"コンクリート造、面積8.5㎡、洗い場及びイチタライ付","structure_material":"コンクリート造","registered":"2008.03.07(平成20.03.07)","register_no":"47 － 0063","desc":"主屋の西南に位置する。琉球石灰岩を掘削して建造された円筒井戸で、深さ１３ｍを測る。上部は径０．６ｍ高さ０．６２ｍの円筒形に造り、周囲に南北２．２ｍ東西３．３ｍの洗い場を設け、その隅に小型のイチタライ（石盥）を置く。農作物や農具の洗い場である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006959"},{"id":"00006957","register_sub_id":"101","register_pk":"107939","name":"東迎家住宅主屋","kana":"とうげいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国151-1","lat":24.46932552,"lng":123.00437734,"geo_status":"db","era":"昭和28／昭和60改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"47 － 0061","desc":"敷地のほぼ中央に南面して建つ。桁行７間梁間４間規模の寄棟造で琉球赤瓦葺とする。正面に雨端を設け、内部は一番座と二番座、各裏座と台所からなる。軸部にチャーギ材、床組や野地にダイミョウ竹を用いる。八重山地方の伝統的な形態や仕様が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006957"},{"id":"00006958","register_sub_id":"101","register_pk":"107940","name":"東迎家住宅水タンク","kana":"とうげいけじゅうたくみずたんく","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県八重山郡与那国町字与那国151-1","lat":24.46938863,"lng":123.00434172,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"コンクリート造、面積4.8㎡","structure_material":"コンクリート造","registered":"2008.03.07(平成20.03.07)","register_no":"47 － 0062","desc":"主屋台所の西面北寄りに接して設けられる。東西１．７ｍ南北２．９ｍで、高さ１．６ｍに及ぶ。コンクリート造で、頂部は蓋状に造り、その隅にある簡易な濾過装置を通じて樋からの雨水を水タンクに溜める。生活に必要な施設の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006958"},{"id":"00006310","register_sub_id":"101","register_pk":"107293","name":"渡久山家住宅石垣","kana":"とくやまけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県石垣市字大川340","lat":24.34313875,"lng":124.1601585,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、延長20m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0055","desc":"敷地南角地の門口に位置し、主屋正面に建つ延長１５ｍの石垣と、コの字型平面の石垣により構成される。地元産の粟石を高さ２ｍ程に布積に積む。当地では主屋正面にマイグスクと称する石垣を積むのが通例だが、当家では敷地に合わせて工夫し、独特の構えとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006310"},{"id":"00006309","register_sub_id":"101","register_pk":"107292","name":"渡久山家住宅井戸","kana":"とくやまけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字大川340","lat":24.34322586,"lng":124.1600681,"geo_status":"db","era":"明治27／昭和初期増設","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、面積1.1㎡、洗い場及び滑車受付","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0054","desc":"主屋の左前方に位置し、井戸枠は琉球石灰岩製で、直径１．２ｍ、高さ０．５ｍである。水汲み用のコンクリート製滑車受けを、井戸枠に沿わせて建て、井戸枠の周囲は３ｍ四方の洗い場で囲む。井戸水利用の歴史を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006309"},{"id":"00006258","register_sub_id":"101","register_pk":"107242","name":"渡久山家住宅主屋","kana":"とくやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県石垣市字大川340","lat":24.34319342,"lng":124.16019169,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0052","desc":"敷地中央に建つ。南北棟の寄棟屋根に、一段低く矩折れに寄棟が付く。建築面積１２８㎡、木造平屋建、本瓦葺。一番座と二番座、各裏座を田の字型に配し、左方奥に台所が接続する。伝統的な間取りであるが、一、二番座境の柱や縁側隅の壁を省略するなど、開放的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006258"},{"id":"00006504","register_sub_id":"101","register_pk":"107487","name":"渡久山家住宅フリヤー","kana":"とくやまけじゅうたくふりやー","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字大川340","lat":24.343283,"lng":124.160149,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、面積16㎡","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"47 － 0053","desc":"主屋の左奥に位置する、大型のフリヤー（便所兼豚小屋）。平面積１６㎡、高さ１．５ｍ、石造。琉球石灰岩と粟石の切石を組み合わせて築き、３区画に仕切る。上部構造は失われているが、基部はよく保存され、区画ごとにトーニ（豚の餌桶）も残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006504"},{"id":"00006670","register_sub_id":"101","register_pk":"107653","name":"八重山民俗園旧牧志家住宅主屋","kana":"やえやまみんぞくえんきゅうまきしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県石垣市字名蔵967-1","lat":24.4042764,"lng":124.14427228,"geo_status":"db","era":"大正12／昭和55移築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"47 － 0058","desc":"寄棟造本瓦葺で入母屋造屋根の玄関を付ける。もと診療所兼住宅の居室部分で、トコと棚のある一番座と二番座、三番座からなり、四周に縁廊下を廻し、正・側面に雨端を設ける。間柱を省略した間取りで、軒や天井を高くし、開放的な空間を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006670"},{"id":"00006671","register_sub_id":"101","register_pk":"107654","name":"八重山民俗園旧森田家住宅主屋","kana":"やえやまみんぞくえんきゅうもりたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県石垣市字名蔵967-1","lat":24.40402566,"lng":124.14453197,"geo_status":"db","era":"明治42／昭和59移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"47 － 0059","desc":"寄棟造平入本瓦葺で、正面右手寄りに寄棟造玄関、左側面に棟続きでトーラやクールを付設する。前後２列になり、前面には右手から一番座、二番座、三番座が並び、背面に各裏座、その外側に縁や雨端を設ける。伝統的な士族住宅で、規模の大きい遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006671"},{"id":"00007948","register_sub_id":"101","register_pk":"128552","name":"屋宜家住宅アサギ","kana":"やぎけじゅうたくあさぎ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県島尻郡八重瀬町字大頓1172","lat":26.12727111,"lng":127.73703488,"geo_status":"db","era":"昭和30頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"47-0072","desc":"主屋の東南に南北棟で建つ。桁行６．６ｍ梁間３．８ｍの木造平屋建、寄棟造セメント瓦葺で、西面と南面を葺き降ろす。南に仏間、北に六畳を配し、西面から南面にかけて雨端をまわす。材は杉やチャーギで、背面や四隅に板壁を設ける。装飾のない質実な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007948"},{"id":"00007951","register_sub_id":"101","register_pk":"128555","name":"屋宜家住宅石垣","kana":"やぎけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県島尻郡八重瀬町字大頓1172","lat":26.1271699,"lng":127.73693489,"geo_status":"db","era":"昭和27／昭和29改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"石造、延長50m","structure_material":"石造","registered":"2009.11.02(平成21.11.02)","register_no":"47-0075","desc":"敷地南辺で東・西から延び、中央で北に折れ、敷地内への通路を造る。総延長は５０ｍに及ぶ。地元八重瀬町港川産の琉球石灰岩を四段に積み、高さ１．３ｍとする。石垣際の花樹と主屋の赤瓦に目地漆喰、そして粟石の風合いが独特の敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007951"},{"id":"00007949","register_sub_id":"101","register_pk":"128553","name":"屋宜家住宅井戸","kana":"やぎけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県島尻郡八重瀬町字大頓1172","lat":26.12737991,"lng":127.73701514,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"石造、面積3.6㎡","structure_material":"石造","registered":"2009.11.02(平成21.11.02)","register_no":"47-0073","desc":"主屋裏座の東、道路際から少し下がった位置に所在。円形に地盤を掘り込み、雨水を溜め、生活用水として使用する。上部は円周に沿って立ち上げ、モルタルで仕上げ、その周囲をＬ字形に切石を積む。石材は地元の港川で産出する琉球石灰岩。敷地内貯水設備の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007949"},{"id":"00007947","register_sub_id":"101","register_pk":"128551","name":"屋宜家住宅主屋","kana":"やぎけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"沖縄県","address":"沖縄県島尻郡八重瀬町字大頓1172","lat":26.12733247,"lng":127.73694047,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"47-0071","desc":"通りの西に占める敷地の北寄りに南面して建つ。桁行１３ｍ梁間６．６ｍの木造平屋建、寄棟造赤瓦葺で目漆喰塗。一番座と二番座、三番座、裏座、台所からなり、南・東面に雨端をまわす。一番座にはトコと棚、二番座には仏壇を設ける。地域的な特色をよく残す建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007947"},{"id":"00007950","register_sub_id":"101","register_pk":"128554","name":"屋宜家住宅ヒンプン","kana":"やぎけじゅうたくひんぷん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"沖縄県","address":"沖縄県島尻郡八重瀬町字大頓1172","lat":26.1272255,"lng":127.7369996,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"石造、延長3.6m","structure_material":"石造","registered":"2009.11.02(平成21.11.02)","register_no":"47-0074","desc":"主屋の南方に位置する。地元八重瀬町港川産の琉球石灰岩を切石積にする。基礎石上に五段積み上げ、高さ１．６ｍを測る。長さ３．６ｍで、厚さ２４㎝。各段とも２、３枚の石で構成され、３ｍ近い長い石材が使われる。重厚で、沖縄らしい屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007950"},{"id":"00006118","register_sub_id":"101","register_pk":"107102","name":"琉球村旧大城家住宅主屋","kana":"りゅうきゅうむらきゅうおおしろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.4289338,"lng":127.77478344,"geo_status":"db","era":"江戸末期／昭和57移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0030","desc":"首里士族の家系で，琉球王府の大臣職を務めた与那原家が首里に建設。桁行７間，梁間３間半規模，寄棟造，赤瓦葺の木造平屋建で，東方に各６畳の一番座と二番座とを並べ，その北方に裏座，西方には三番座と台所を配す。東面と南面の雨端を土庇状とするのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006118"},{"id":"00005956","register_sub_id":"101","register_pk":"106941","name":"琉球村旧島袋家住宅主屋","kana":"りゅうきゅうむらきゅうしまぶくろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.42961576,"lng":127.77454319,"geo_status":"db","era":"明治20頃／昭和57移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0025","desc":"琉球王府の貢納穀類の秤役を務めた旧家。桁行８間，梁行４間規模，寄棟造，赤瓦葺の木造平屋建で，南西に各４畳半の一番座と二番座を並べ，東側に裏座，北方に三番座と台所を配する。四周にイヌマキの柱に支持された雨端を廻した沖縄の伝統的民家の形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005956"},{"id":"00005957","register_sub_id":"101","register_pk":"106942","name":"琉球村旧島袋家住宅高倉","kana":"りゅうきゅうむらきゅうしまぶくろけじゅうたくたかくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.42966961,"lng":127.77438991,"geo_status":"db","era":"明治20頃／昭和57移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、茅葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0026","desc":"穀物類や種類を保存するための高床倉。桁行２．８ｍ，梁間２．１ｍに４本の丸柱を立て，高さ２．３ｍに床を張り，寄棟造，茅葺の屋根を架ける。高床は桁行４．３ｍ，梁行３．８ｍ規模である。柱外側の床の傾斜は１０～２０度程度で，奄美地方の高倉に近い形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005957"},{"id":"00006094","register_sub_id":"101","register_pk":"107079","name":"琉球村旧玉那覇家住宅主屋","kana":"りゅうきゅうむらきゅうたまなはけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.42963573,"lng":127.77476434,"geo_status":"db","era":"明治24頃／昭和57移築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0027","desc":"拝領地名を姓とした首里士族の一族で，１８世紀初頭に恩納村に移住と伝える。北西に床と仏壇をもつ一番座と二番座を並べ，西側に裏座，南方に三番座と台所を配する。桁行７間，梁間３間，寄棟造，赤瓦葺の木造平屋建で，東と北に雨端を廻した伝統的形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006094"},{"id":"00006095","register_sub_id":"101","register_pk":"107080","name":"琉球村旧西石垣家住宅主屋","kana":"りゅうきゅうむらきゅうにしいしがきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.42923466,"lng":127.77450136,"geo_status":"db","era":"明治末期／昭和56移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0028","desc":"西石垣家が昭和３０年代に買い取って自宅としたもので，桁行４間半，梁行３間半，寄棟造，赤瓦葺の木造平屋建。もとは４室構成と推測される。間仕切りを取り払い，４方開放型に改造されているが，東・南・北３面に雨端を廻すなど沖縄の伝統的民家形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006095"},{"id":"00006096","register_sub_id":"101","register_pk":"107081","name":"琉球村旧比嘉家住宅主屋","kana":"りゅうきゅうむらきゅうひがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.429235,"lng":127.774307,"geo_status":"db","era":"明治10頃／昭和57移築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0029","desc":"琉球建国の神アマミキョに関わる家柄と伝えられ，代々聖地の管理を務め，一番座に聖石を祀るための床の間を設けるのが特徴。桁行６間半，梁間３間，寄棟造，赤瓦葺の木造平屋建で，南側を三番座と台所とする平面形式をもち，東面北方と北面に雨端を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006096"},{"id":"00006119","register_sub_id":"101","register_pk":"107103","name":"琉球村旧平田家住宅フール","kana":"りゅうきゅうむらきゅうひらたけじゅうたくふーる","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"沖縄県","address":"沖縄県国頭郡恩納村字山田1130","lat":26.42931932,"lng":127.77484831,"geo_status":"db","era":"明治30頃／昭和57移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"石造、面積20㎡","structure_material":"石造","registered":"2007.05.15(平成19.05.15)","register_no":"47 － 0031","desc":"琉球村中央部東端近くの斜面下に移設されている。便所と豚の飼育場を兼ねたもので，琉球石灰岩で築く。外形は約５ｍ×約４ｍで，東側に飼育場，西側に便所を南北に３連並べる。各飼育場は１．２ｍ×２．４ｍ，深さ０．５ｍで，東壁にニッチ状の日除けを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006119"},{"id":"00015157","register_sub_id":"101","register_pk":"530581","name":"宮下家住宅主屋","kana":"みやしたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市磯子区森二丁目481","lat":35.39804167,"lng":139.61405556,"geo_status":"db","era":"昭和8年頃／昭和中期増築、令和5年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":null,"register_no":null,"desc":"国道一六号沿いの敷地に東面して建つ、旧別荘。木造二階建、外壁黄土色モルタル塗仕上の洋館と平屋の和館をＬ字に配す。洋館はエンタシス付角柱を飾る玄関廻りが特徴的で、和館は筬欄間など繊細なつくりの和洋折衷住宅。根岸湾の近代別荘開発の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015157"}];
